use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl SourceMap { # [doc = " Returns `Some(span)`, a union of the LHS and RHS span. The LHS must precede the RHS. If"] # [doc = " there are gaps between LHS and RHS, the resulting union will cross these gaps."] # [doc = " For this to work,"] # [doc = ""] # [doc = "    * the syntax contexts of both spans much match,"] # [doc = "    * the LHS span needs to end on the same line the RHS span begins,"] # [doc = "    * the LHS span must start at or before the RHS span."] fn merge_spans (& self , sp_lhs : Span , sp_rhs : Span) -> Option < Span > { if ! sp_lhs . eq_ctxt (sp_rhs) { return None ; } let lhs_end = match self . lookup_line (sp_lhs . hi ()) { Ok (x) => x , Err (_) => return None , } ; let rhs_begin = match self . lookup_line (sp_rhs . lo ()) { Ok (x) => x , Err (_) => return None , } ; if lhs_end . line != rhs_begin . line { return None ; } if (sp_lhs . lo () <= sp_rhs . lo ()) && (sp_lhs . hi () <= sp_rhs . lo ()) { Some (sp_lhs . to (sp_rhs)) } else { None } } # [doc = " Converts an absolute `BytePos` to a `CharPos` relative to the `SourceFile`."] fn bytepos_to_file_charpos (& self , bpos : BytePos) -> CharPos { let idx = self . lookup_source_file_idx (bpos) ; let sf = & (* self . files . borrow () . source_files) [idx] ; let bpos = sf . relative_position (bpos) ; sf . bytepos_to_file_charpos (bpos) } }